def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    rich_threats = 0
    urgent_opponents = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) >= 120:
                rich_threats += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opponents += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))

    if not alive_opponents:
        return min(budget, 18.0)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    second_prev = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else highest_prev

    tight_supply = supply <= 17
    roomy_supply = supply >= 22

    survival_mode = (hp <= 2) or (no_water >= 1)
    caution_mode = (hp <= 4)

    if survival_mode:
        if tight_supply:
            bid = max(92.0, second_prev + 3.0)
        else:
            bid = max(78.0, min(highest_prev * 0.72, 108.0))
        return float(min(budget, bid))

    if roomy_supply and hp >= 6 and no_water == 0:
        bid = 8.0 if rich_threats >= 2 else 14.0
        if highest_prev < 60:
            bid = max(bid, highest_prev + 1.0)
        return float(min(budget, bid))

    if tight_supply:
        if rich_threats >= 2:
            bid = 32.0 if hp >= 7 else 68.0
        else:
            bid = max(40.0, second_prev + 2.0)
        if caution_mode:
            bid = max(bid, 72.0)
        return float(min(budget, bid))

    if highest_prev >= 140:
        bid = 20.0 if hp >= 6 else 74.0
    elif highest_prev >= 110:
        bid = 24.0 if hp >= 7 else 70.0
    elif highest_prev >= 70:
        bid = max(38.0, second_prev + 1.5)
    else:
        bid = max(28.0, highest_prev + 2.0)

    if urgent_opponents >= 2 and hp >= 6 and no_water == 0:
        bid *= 0.85

    reserve_target = DAILY_SALARY * max(0, 10 - int(day)) * 0.18
    max_spend = budget
    if budget > reserve_target:
        max_spend = budget

    return float(min(max_spend, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Identify alive opponents and extract yesterday bids
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    yesterday_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {})
        if isinstance(prev, dict) and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev['bid']))
            except Exception:
                pass

    # Base bid policy: conserve budget unless I’m in danger
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    # Escalation triggers
    danger = (hp <= 3.0) or (no_water_days >= 2)

    # Use yesterday highest bid as proxy for opponent aggressiveness
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
    else:
        highest_prev_bid = 0.0

    # Supply pressure: higher supply reduces marginal need to overbid
    # Normalize supply within [15,25]
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    else:
        supply_norm = 0.5
    supply_norm = max(0.0, min(1.0, float(supply_norm)))

    # Target bid
    # If opponents were aggressive yesterday, slightly undercut to save budget unless danger.
    if highest_prev_bid >= DAILY_SALARY * 1.6:  # ~144
        if danger:
            target = max(highest_prev_bid * 0.98, DAILY_SALARY * 0.85)
        else:
            target = max(highest_prev_bid * 0.82, DAILY_SALARY * (0.45 + 0.25 * supply_norm))
    elif highest_prev_bid >= DAILY_SALARY * 1.1:  # ~99
        if danger:
            target = max(highest_prev_bid * 0.95, DAILY_SALARY * 0.75)
        else:
            target = max(highest_prev_bid * 0.75, DAILY_SALARY * (0.40 + 0.20 * supply_norm))
    else:
        if danger:
            target = DAILY_SALARY * 0.90
        else:
            # Conservative default
            target = DAILY_SALARY * (0.50 + 0.15 * supply_norm)

    # Ensure bid is within budget and non-negative
    if budget <= 0:
        return 0.0

    target = float(target)
    if target < 0.0:
        target = 0.0

    # Cap to budget; also avoid extreme spending
    max_reasonable = min(budget, DAILY_SALARY * 1.9)
    bid = min(target, max_reasonable)

    return float(bid)
